mapper.select:
select id, registration_no, season_id, team_id, captain_member_id, captain_player_id, contact_name, contact_mobile, contact_email, registration_status, lineup_count, submitted_time, audit_time, withdrawal_time, withdrawal_reason, current_auditor_id, remark, create_time, update_time, is_delete from basket_tournament_registration where is_delete = 0
and registration_no like concat('%', #{registrationNo}, '%')
and season_id = #{seasonId}
and team_id = #{teamId}
and registration_status = #{registrationStatus}
order by submitted_time desc, create_time desc
